def is_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    try:
        # Numerator N = (x+1)^y
        N = (x + 1)**y
        # Denominator D = x^z + 1
        D = x**z + 1

        # Check for positive integer result
        # Since x, y, z >= 1, N and D are always positive.
        if N % D == 0:
            return True
        else:
            return False
    except OverflowError:
        # This shouldn't happen for x,y,z <= 10, but good practice.
        return False

good_triples = []
for x in range(1, 11):
    for y in range(1, 11):
        for z in range(1, 11):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print("Found good triples:")
for triple in good_triples:
    print(triple)

print(f"Total good triples found: {len(good_triples)}")

def is_good_triple(x, y, z):
    # Check if (x+1)^y is divisible by x^z + 1
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Since x, y, z are positive integers, both numerator and denominator are positive integers.
    return numerator % denominator == 0

count = 0
max_val = 99

for x in range(1, max_val + 1):
    for y in range(1, max_val + 1):
        for z in range(1, max_val + 1):
            if is_good_triple(x, y, z):
                count += 1

print(f"Total count of good triples: {count}")
